figure.artwork:
DVV = {
  ? 1: Dot,                     ; Present for writes
  ? 2: Deps,                    ; Present for reads/writes
  ? 3: [* NodeId],              ; Pruned writers (OPTIONAL)
  ? 4: CIDOrV1                  ; Current state CID (OPTIONAL)
}

Dot = [writer: NodeId, counter: uint, ? cid: CIDOrV1]
Deps = { * NodeId => counter: uint }

function merge(A, B):
    INF = 4294967295  # 0xFFFFFFFF sentinel for pruned writers
    C = {}
    for w in keys(A.deps) union keys(B.deps):
        a = INF if w in A.pruned else A.deps.get(w, 0)
        b = INF if w in B.pruned else B.deps.get(w, 0)
        C.deps[w] = max(a, b)
        if C.deps[w] == INF:
            C.pruned.add(w)

    if A.dot.counter > B.dot.counter:
        C.dot = A.dot
    else if B.dot.counter > A.dot.counter:
        C.dot = B.dot
    else:
        C.dot = lower(A.dot, B.dot)  # deterministic tie-break
                                     # e.g. lexicographic on writer NodeId

    # CID resolution
    if A.cid and not B.cid:
        C.cid = A.cid
    elif B.cid and not A.cid:
        C.cid = B.cid
    elif A.cid and B.cid and A.cid != B.cid:
        # Both exist and conflict: resolve via DVV ordering
        if A.dot.counter > B.dot.counter:
            C.cid = A.cid
        elif B.dot.counter > A.dot.counter:
            C.cid = B.cid
        else:
            C.cid = lexicographically_lower(A.cid, B.cid)

    return C

function find_witnesses(target, epoch, k=7):
    # Query Coral DHT on 3 independent paths
    candidates = {}
    for path in [1..LOOKUP_PATHS]:
        path_candidates = coral_dht.find_node(target, k=16, path=path)
        # Filter by reachability
        path_candidates = filter_reachable(path_candidates)
        candidates[path] = path_candidates

    # Cross-path validation
    witness_sets = []
    for path, cand in candidates.items():
        ordered = sort(cand, key=lambda n: distance(target, n.id))
        witness_sets.append(set(ordered[0:k]))

    # Check consensus
    if majority_consensus(witness_sets, SPILLOVER_THRESHOLD):
        return consensus_set

    # Trigger spillover
    return spillover_mechanism(target, witness_sets)

Operation = {
  kind: tstr,              ; operation kind
  subject: bytes,          ; opaque subject identifier
  body: any                ; application-defined payload
}

; ---- Base CID (raw digest, 32 bytes) ----
CID = bytes .size 32      ; SHA-256 or BLAKE3 digest

; ---- CIDv1 (tagged identifier) ----
CIDv1 = {
  hash_algo: uint,          ; 0 = SHA-256, 1 = BLAKE3
  digest: bytes .size 32    ; The raw hash digest
}

; ---- Union type for all message definitions ----
CIDOrV1 = CID / CIDv1

HashAlgo = &{
  sha256: 0,   ; MUST implement
  blake3: 1    ; MAY implement
}

CIDv1 = {
  hash_algo: uint,          ; 0 = SHA-256, 1 = BLAKE3
  digest: bytes .size 32    ; The raw hash digest
}

signing_payload = QUIP-CBOR-encode(
  message_array_with_signature_element_removed
)

Address = {
  family: uint,          ; 4 = IPv4, 6 = IPv6
  ip: bytes,             ; 4 bytes for IPv4, 16 bytes for IPv6
  port: uint             ; 0-65535
}

RelayDiscovery = [ "quip-v1", "relay_discovery", request_id: bytes .size 16, ; Unique per outstanding discovery requester: NodeId, target: NodeId, ; Who the requester wants to reach max_hops: uint, ; Maximum relay hops (default: RELAY_HOP_LIMIT) timestamp: uint, signature: bytes .size 64 ]
RelayResponse = [ "quip-v1", "relay_response", request_id: bytes .size 16, ; Echoed from RelayDiscovery target: NodeId, ; Echoed from RelayDiscovery requester: NodeId, relays: [* RelayEntry], timestamp: uint, signature: bytes .size 64 ]
RelayEntry = { relay_id: NodeId, external_addr: Address, capacity: uint, load: uint, cost: uint ; Application-defined cost metric }

RelayChain = {
  hops: [* RelayHop],
  target: NodeId,
  ttl: uint
}

RelayHop = {
  relay_id: NodeId,
  next_hop: Address,
  encrypted_key: bytes         ; HPKE seal (see below)
}

section.t:
Relay-hop key encapsulation: encrypted_key
        is an HPKE  seal in mode_base,
        using the suite:

figure.artwork:
{
  cluster_id: bytes .size 16,
  size: uint,                ; Estimated cluster size
  ctime: uint,               ; Cluster creation time (Unix ms)
  signature: bytes .size 64  ; Signed by node
}

ol.li:
Once a peer has joined the DHT, all further routing and 
          witness discovery MUST use normal Kademlia lookups; 
          bootstrap nodes carry no special trust after initial join.

ul.li:
Full CIDv1 with multicodec: Full IPFS-compatible CIDs 
        for interoperability with the broader content-addressed ecosystem, 
        building on the CIDv1 tagging introduced in this version.
